import{z as A,x as p,o as t,c as m,q as n,j as r,D as E,d as i,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"变形掩模倍率","description":"","frontmatter":{"title":"变形掩模倍率","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/anamorphic-mask-mag.md","filePath":"litho/anamorphic-mask-mag.md","lastUpdated":1791413859000}'),h={name:"litho/anamorphic-mask-mag.md"};function d(B,a,D,C,u,c){const o=p("Mermaid");return t(),m("div",null,[a[2]||(a[2]=n('<h1 id="变形掩模倍率" tabindex="-1">变形掩模倍率 <a class="header-anchor" href="#变形掩模倍率" aria-label="Permalink to &quot;变形掩模倍率&quot;">​</a></h1><div class="epigraph"><p>硅片侧 0.55 若仍用各向同性 4×，掩模角会先死；狭缝向约 4×、扫描向约 8× 是把 6 英寸版和多层窗一起保住的倍率对。</p><footer>—— 据 van Schoot 等对 High-NA 变形倍率的公开光学论述</footer></div><p><a href="/litho/high-na-resist-budget">上一课</a>把轴向胶厚和焦深收进同一张预算。缺口是物面：胶再薄，掩模侧角度仍由 NA 除以倍率决定。本课钉变形掩模倍率（约 4×/8×）。真空磁浮台如何跑这条不对称同步，在<a href="/litho/euv-maglev-stage">工件台</a>与同步课展开，这里只把倍率写进掩模与 OPC 合同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>掩模 NA 等于硅片 NA 除以倍率。各向同性 4×、NA 0.55 给出掩模 NA ≈ 0.138，主光线与角谱把 <a href="/litho/euv-multilayer-mirror">Mo/Si</a> 和吸收体阴影同时打出窗；6 英寸空白版也放不下光瞳。<a href="/litho/anamorphic-projection">变形光学</a> 已经给出机器几何：狭缝向保持约 4×、扫描向提高倍率。本课的缺口是这张倍率对<strong>掩模</strong>意味着什么——场、写版、CD 定义、OPC 坐标系——而不是再推一遍 CRA。</p><p>胶厚课解决的是像面薄膜；倍率课解决的是物面缩放不对称。两者都是 0.55 能落地的条件，不是重复。</p><p><span class="marginnote">直觉类比：各向异性倍率像只在横向拉伸的哈哈镜——照片被横向压一半保存，还原时横向用 2 倍比例尺、纵向用 1 倍。掩模与硅片之间就是这样两本比例尺的账。</span></p><h3 id="_8×-不是「版上图形放大一倍就完」" tabindex="-1">8× 不是「版上图形放大一倍就完」 <a class="header-anchor" href="#_8×-不是「版上图形放大一倍就完」" aria-label="Permalink to &quot;8× 不是「版上图形放大一倍就完」&quot;">​</a></h3><p>扫描向 8×：每场硅片行程在该方向减半（半场 16.5 mm），掩模上该方向的场更长，同一 6 英寸版装得下角谱。狭缝向 4×：26 mm 狭缝与 NXE 的场宽兼容，晶圆台扫描速度不必变——代价是掩模台在扫描向要跑 8 倍速。OPC、MRC、写掩模网格必须按方向用不同倍率还原到硅片纳米，不能再用各向同性 4× 的口令画一条边。</p><p><span class="marginnote">van Schoot 的论证对象是光学约束，不是某张产品海报上的 wph。本课引用 4×/8× 与半场几何，不把未核实吞吐写成事实。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计与 TAPOUT 在硅片坐标里画；掩模厂在变形物面坐标里写。中间要一张各向异性的放大：x、y 各一套倍率、各一套 MEF。SRAF 宽度、MRC 最小间距在版上是各向异性的合同，回到硅片又必须各向同性地满足电学规则。碎片长度、jog 规则按方向拆开，否则 8× 方向上「看起来很细」的助条在硅片上并不细，或反过来。</p><p>套刻与拼接：半场约 26 mm × 16.5 mm 是倍率几何的推论。层间若一张 0.33 全场、一张 0.55 半场，倍率定义必须在套刻模型里显式出现。这与胶厚预算正交：一个管 z，一个管物面缩放。</p><p><span class="marginnote">为什么重要：混跑产线里一层是 0.33 全场、一层是 0.55 半场，套刻模型若不把倍率写成显式参数，全场对半场的网格会整体漂一个比例系数，且随方向不同——这类错查起来极像真套刻漂移。</span></p><h3 id="写版与检测" tabindex="-1">写版与检测 <a class="header-anchor" href="#写版与检测" aria-label="Permalink to &quot;写版与检测&quot;">​</a></h3><p>电子束按掩模纳米寻址。变形后，硅片上同样的 1 nm CD 误差在两个方向对应不同的版上误差。检测像素、缺陷打印阈值也要按方向解释。掩模 3D 模型的入射角随方向变，吸收体阴影已经不对称，再叠变形倍率，左右与 HV 必须分开校准。</p><p><span class="marginnote">换算一把尺：扫描向 8×，版上画 8 nm 才等于硅片上 1 nm；狭缝向 4×，版上 4 nm 就是 1 nm。写版机的同一格寻址网格，在 8× 方向对应更细的硅片纳米，在 4× 方向粗一倍——误差预算必须按方向分开记。</span></p>',17)),(t(),r(s,null,{default:E(()=>[l(o,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E7%89%88%E6%9C%BA%E6%8C%89%E6%8E%A9%E6%A8%A1%E7%BA%B3%E7%B1%B3%E5%AF%BB%E5%9D%80%22%5D%20--%3E%20S4%5B%22%E7%8B%AD%E7%BC%9D%E5%90%91%204x%3A%20%E7%89%88%E4%B8%8A%204%20nm%20%3D%20%E7%A1%85%E7%89%87%201%20nm%22%5D%0A%20%20W%20--%3E%20S8%5B%22%E6%89%AB%E6%8F%8F%E5%90%91%208x%3A%20%E7%89%88%E4%B8%8A%208%20nm%20%3D%20%E7%A1%85%E7%89%87%201%20nm%22%5D%0A%20%20S4%20--%3E%20CD%5B%22%E5%90%8C%E4%B8%80%E7%A1%85%E7%89%87%20CD%20%E8%AF%AF%E5%B7%AE%E5%AF%B9%E5%BA%94%E4%B8%8D%E5%90%8C%E7%89%88%E4%B8%8A%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20S8%20--%3E%20CD%0A%20%20CD%20--%3E%20OPC%5B%22OPC%20%2F%20MRC%20%2F%20%E6%A3%80%E6%B5%8B%E9%98%88%E5%80%BC%E5%88%86%E8%BD%B4%E8%A7%A3%E9%87%8A%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"投影把掩模频谱按两个方向不同的缩放送进光瞳。MEF、PV-band、线端缩短在 H 与 V 上本来就因阴影不同；变形倍率把「版上同等改动」变成硅片上不等价的 CD。模型基 OPC 必须用变形成像核，规则 OPC 的各向同性表在这里没有资格。",-1)),a[5]||(a[5]=e("p",null,"工件台同步：掩模台在扫描向约 8 倍晶圆台扫描速度；狭缝向以 4× 对应场宽。同步误差进套刻的杠杆按方向不同。本课只点名这条约定，不写伺服。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"「变形掩模」不是把版图画成椭圆晶体管。设计仍在硅片正交网格上；各向异性只存在于物像缩放和掩模 3D 成像。")],-1)),(t(),r(s,null,{default:E(()=>[l(o,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20DES%5B%22%E7%A1%85%E7%89%87%E5%9D%90%E6%A0%87%E8%AE%BE%E8%AE%A1%22%5D%20--%3E%20MAG%5B%224x%20%E7%8B%AD%E7%BC%9D%E5%90%91%20%2F%208x%20%E6%89%AB%E6%8F%8F%E5%90%91%22%5D%0A%20%20MAG%20--%3E%20MASK%5B%226%20%E8%8B%B1%E5%AF%B8%E5%8F%98%E5%BD%A2%E7%89%A9%E9%9D%A2%22%5D%0A%20%20MASK%20--%3E%20OPC%5B%22%E6%96%B9%E5%90%91%E7%9B%B8%E5%85%B3%20OPC%20%2F%20MRC%22%5D%0A%20%20MAG%20--%3E%20FIELD%5B%22%E5%8D%8A%E5%9C%BA%E5%87%A0%E4%BD%95%22%5D%0A%20%20MAG%20--%3E%20SYNC%5B%22%E6%8E%A9%E6%A8%A1%E5%8F%B0%E9%80%9F%E5%BA%A6%E6%AF%94%E6%8C%89%E5%90%91%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写胶倒塌，也不展开半场拼接工艺。不要把 4×/8× 写成已经改过的产品倍率表以外的数。掩模厂的写场、检测视场和空白版利用率都按这张不对称缩放排，不能仍按 NXE 的各向同性 4× 排产。后课默认：说到 High-NA 掩模，先问方向倍率，再问吸收体厚度。</p><p>引用以 van Schoot 公开论文与 ASML High-NA 光学叙述为准。</p><p><span class="marginnote">0.33 NXE 仍是各向同性约 4×。不要把本课的 8× 套回 NXE 掩模厂规则。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>High-NA 用约 4×/8× 变形倍率，保住掩模角、6 英寸版和扫描速度比。</li><li>OPC、MRC、写版网格必须按方向还原到硅片纳米。</li><li>半场是倍率几何推论，与胶厚预算正交。</li><li>各向同性 4× 的规则 OPC 在此没有合同资格。</li><li>写版寻址按掩模纳米；同一硅片纳米在两方向对应不同版上误差。</li><li>出处：van Schoot 等 High-NA 变形光学公开论述。</li></ul>',6))])}const P=A(h,[["render",d]]);export{g as __pageData,P as default};
